pub static ErrGlobalIndexNotExplicitlySet: LazyLock<Error> =
    LazyLock::new(|| ClassDDL.new_std(errno::ErrGlobalIndexNotExplicitlySet));

/// ErrWarnGlobalIndexNeedManuallyAnalyze is used for global indexes,
/// which cannot trigger automatic analysis when it contains prefix columns or virtual generated columns.
pub static ErrWarnGlobalIndexNeedManuallyAnalyze: LazyLock<Error> =
    LazyLock::new(|| ClassDDL.new_std(errno::ErrWarnGlobalIndexNeedManuallyAnalyze));

/// ErrCannotSetAffinityOnTable is returned when set an invalid affinity on a table
pub static ErrCannotSetAffinityOnTable: LazyLock<Error> = LazyLock::new(|| {
    ClassDDL.new_std_err(
        errno::ErrInvalidAffinityOption,
        &ErrMessage::new("Can not set %s on a %s.", &[]),
    )
});

/// ErrInvalidTableAffinity is returned when set an invalid affinity value on a table
pub static ErrInvalidTableAffinity: LazyLock<Error> =
    LazyLock::new(|| ClassDDL.new_std(errno::ErrInvalidAffinityOption));

